// Pure helpers shared by APK and web. They intentionally do not access UI or storage.
var PIKET_RELIABILITY = {
  confidence: function(input) {
    input=input||{};
    if(input.manualReview) return {key:"review",label:"нужна сверка"};
    if(input.recovering) return {key:"recovering",label:"восстанавливается"};
    if(input.fixQuality==="good" && (+input.fixAgeMs||0)<=4000 && (+input.accuracy||999)<=35)
      return {key:"exact",label:"точная"};
    return {key:"calculated",label:"расчётная"};
  },
  requiredAverageKmh: function(distanceM,secondsLeft) {
    distanceM=+distanceM; secondsLeft=+secondsLeft;
    if(!isFinite(distanceM)||!isFinite(secondsLeft)||distanceM<0||secondsLeft<=0) return null;
    return distanceM/secondsLeft*3.6;
  },
  directionMismatch: function(previousTrackM,currentTrackM,towards,minMovementM) {
    var d=(+currentTrackM)-(+previousTrackM), min=+minMovementM||120;
    if(!isFinite(d)||Math.abs(d)<min) return false;
    return towards==="obratno" ? d>0 : d<0;
  },
  checkpointCorrection: function(residualM,confirmations) {
    residualM=+residualM||0; confirmations=+confirmations||0;
    if(Math.abs(residualM)<=50) return {apply:residualM,confirmed:true};
    if(Math.abs(residualM)<=250 && confirmations>=2) return {apply:residualM,confirmed:true};
    if(confirmations>=4) return {apply:residualM,confirmed:true};
    return {apply:0,confirmed:false};
  },
  triggerAudit: function(expectedLeadM,actualAheadM) {
    var delta=Math.round((+actualAheadM||0)-(+expectedLeadM||0));
    return {deltaM:delta,ok:Math.abs(delta)<=250};
  }
};
